<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x4E8C;&#x7EF4;&#x7801;&#x7F8E;&#x5316;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="input-section"><text class="section-title">&#x5185;&#x5BB9;</text><input class="text-input" v-model="qrText" placeholder="&#x8F93;&#x5165;&#x6587;&#x5B57;&#x6216;URL" /></view><view class="style-section"><text class="section-title">&#x989C;&#x8272;</text><view class="color-pickers"><view class="cp-row"><text class="cp-label">&#x524D;&#x666F;</text><input type="color" v-model="fgColor" class="color-input" /></view><view class="cp-row"><text class="cp-label">&#x80CC;&#x666F;</text><input type="color" v-model="bgColor" class="color-input" /></view></view></view><view class="style-section"><text class="section-title">&#x70B9;&#x6837;&#x5F0F;</text><view class="dot-styles"><view class="dot-btn" :class="{active: dotStyle==='square'}" @click="dotStyle='square'">&#x25A0;</view><view class="dot-btn" :class="{active: dotStyle==='round'}" @click="dotStyle='round'">&#x25CF;</view><view class="dot-btn" :class="{active: dotStyle==='diamond'}" @click="dotStyle='diamond'">&#x25C6;</view></view></view><view class="qr-preview"><canvas canvas-id="qrCanvas" style="width:400rpx;height:400rpx;margin:0 auto;display:block"></canvas></view><view class="save-btn" @click="saveQR"><text>&#x4FDD;&#x5B58;&#x56FE;&#x7247;</text></view></view></view></template><script setup>import { ref, watch, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const qrText = ref("https://example.com")
const fgColor = ref("#000000")
const bgColor = ref("#ffffff")
const dotStyle = ref("square")
function goBack() { uni.navigateBack() }
function drawQR() { if (!qrText.value) return; var ctx = uni.createCanvasContext("qrCanvas"); var size = 400; ctx.setFillStyle(bgColor.value); ctx.fillRect(0, 0, size, size); var cells = 21; var cellSize = size / cells; ctx.setFillStyle(fgColor.value); var pattern = generatePattern(qrText.value); for (var i = 0; i < cells; i++) for (var j = 0; j < cells; j++) { if (pattern[i] && pattern[i][j]) { var x = j * cellSize, y = i * cellSize; if (dotStyle.value === "square") ctx.fillRect(x, y, cellSize, cellSize); else if (dotStyle.value === "round") { ctx.beginPath(); ctx.arc(x+cellSize/2, y+cellSize/2, cellSize/2, 0, Math.PI*2); ctx.fill() } else { ctx.beginPath(); ctx.moveTo(x+cellSize/2, y); ctx.lineTo(x+cellSize, y+cellSize/2); ctx.lineTo(x+cellSize/2, y+cellSize); ctx.lineTo(x, y+cellSize/2); ctx.closePath(); ctx.fill() } } } ctx.draw() }
function generatePattern(text) { var cells = 21; var p = []; for (var i = 0; i < cells; i++) { p[i] = []; for (var j = 0; j < cells; j++) { p[i][j] = Math.random() > 0.5 } } for (var i = 0; i < 7; i++) for (var j = 0; j < 7; j++) { p[i][j] = (i===0||i===6||j===0||j===6||(i>=2&&i<=4&&j>=2&&j<=4)); p[i+14][j] = p[i][j+14] = p[i][j] } return p }
function saveQR() { uni.canvasToTempFilePath({ canvasId: "qrCanvas", success: function(res) { uni.saveImageToPhotosAlbum({ filePath: res.tempFilePath, success: function() { uni.showToast({ title: "&#x5DF2;&#x4FDD;&#x5B58;", icon: "success" }) } }) } }) }
watch([qrText, fgColor, bgColor, dotStyle], function() { drawQR() })
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } drawQR() })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#10b981,#059669);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.input-section,.style-section{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.section-title{font-size:28rpx;color:#333;font-weight:600;display:block;margin-bottom:16rpx}.text-input{width:100%;height:80rpx;background:#f5f7fb;border-radius:12rpx;padding:0 16rpx;font-size:28rpx;border:2rpx solid #eee}.color-pickers{display:flex;gap:24rpx}.cp-row{display:flex;align-items:center;gap:12rpx}.cp-label{font-size:26rpx;color:#666}.color-input{width:80rpx;height:60rpx;border:none;border-radius:8rpx}.dot-styles{display:flex;gap:16rpx}.dot-btn{width:80rpx;height:80rpx;background:#f5f7fb;border-radius:12rpx;display:flex;align-items:center;justify-content:center;font-size:36rpx;border:2rpx solid transparent}.dot-btn.active{border-color:#10b981;background:#d1fae5}.qr-preview{background:#fff;border-radius:16rpx;padding:32rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04);display:flex;justify-content:center}.save-btn{background:linear-gradient(135deg,#10b981,#059669);border-radius:16rpx;padding:24rpx;text-align:center}.save-btn text{font-size:30rpx;color:#fff;font-weight:600}</style>